import React, { useState } from 'react';


const CreateFranchise = () => {
  const [formData, setFormData] = useState({
    name: '',
    location: '',
    contactNumber: '',
    status: 'active',
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await API.post('/franchises', formData);
      alert('Franchise created successfully!');
    } catch (error) {
      alert('Error creating franchise: ' + error.response.data.message);
    }
  };

  return (
    <div>
      <h1>Create Franchise</h1>
      <form onSubmit={handleSubmit}>
        <input name="name" placeholder="Name" onChange={handleChange} required />
        <input name="location" placeholder="Location" onChange={handleChange} required />
        <input name="contactNumber" placeholder="Contact Number" onChange={handleChange} required />
        <button type="submit">Create Franchise</button>
      </form>
    </div>
  );
};

export default CreateFranchise;
